register:
import {AuthConfig, SdkConfig, registerInstances} from 'exsited';

registerInstances([
    new SdkConfig(
        new AuthConfig({
            clientName: 'default',
            baseUrl: process.env.EXSITED_BASE_URL,
            clientId: process.env.EXSITED_CLIENT_ID,
            clientSecret: process.env.EXSITED_CLIENT_SECRET,
            redirectUri: process.env.EXSITED_REDIRECT_URI,
        }),
        {raiseOnError: true},
    ),
]);
